    vpnOn: "VPN: {{name}}",
    weakSignal: "Слабкий сигнал Wi-Fi: швидкість падатиме, а зв'язок — обриватися. Підійди ближче до роутера або прибери перешкоди.",
    openWifi: "Ця мережа без пароля (або з WEP, який зламують за хвилини): усі поруч можуть бачити незашифрований трафік. Користуйся VPN або не заходь на важливі сайти.",
    traffic: "Трафік",
