    kind: {
      "ifeo-debugger": { title: "Підміна запуску програми (IFEO)", why: "Windows запускатиме вказану тут програму замість названої. Так шкідливе ПЗ блокує Диспетчер завдань і антивіруси або ховається за знайомою назвою.", todo: "Якщо ти не встановлював засоби налагодження — винеси ключ у карантин." },
      "silent-exit": { title: "Запуск при закритті програми", why: "Коли названа програма закривається, Windows тихо запускає іншу. Рідкісний і непомітний спосіб закріпитися в системі.", todo: "Майже завжди це шкідливе — винеси ключ у карантин." },
      winlogon: { title: "Змінено вхід у систему (Winlogon)", why: "Ці параметри визначають, що запускається при кожному вході в Windows. Звичайно там лише стандартні програми Windows.", todo: "Варто повернути стандартне значення (explorer.exe / userinit.exe) — краще з допомогою фахівця." },
      appinit: { title: "DLL у кожній програмі (AppInit)", why: "Вказані бібліотеки завантажуються в кожну програму з вікном. Сучасне ПЗ так не робить, шкідливе — буває.", todo: "Якщо не впізнаєш бібліотеку — перевір її репутацію." },
      appcert: { title: "DLL при кожному запуску (AppCertDlls)", why: "Ця бібліотека завантажується щоразу, коли щось запускається. Легітимні програми цим майже не користуються.", todo: "Перевір, яка програма її встановила." },
      "lsa-package": { title: "Сторонній пакет у LSA", why: "LSA тримає паролі входу. Сторонній пакет у ній може їх перехоплювати; але так працюють і деякі корпоративні засоби входу.", todo: "Якщо комп'ютер не робочий — це підозріло." },
      "wmi-subscription": { title: "Прихована підписка WMI", why: "Windows сама виконує цю команду за подією (наприклад, щогодини чи при вході). Її не видно ні в автозапуску, ні в планувальнику — улюблений прийом «безфайлових» вірусів.", todo: "Якщо не впізнаєш — зверніться до фахівця або антивіруса: видалення вимагає прав адміністратора." },
      "task-command": { title: "Підозріле завдання планувальника", why: "Завдання виконує команду, якою зазвичай користуються атаки, а не звичайні програми.", todo: "Перевір, хто створив завдання, і вимкни його, якщо не впізнаєш." },
      "run-command": { title: "Підозрілий запис автозапуску", why: "При вході в Windows виконується команда, схожа на атаку.", todo: "Вимкни запис у розділі «Автозапуск» і перевір файл." },
      "startup-file": { title: "Файл у папці автозапуску", why: "Звичайно в папці автозапуску лежать ярлики. Скрипт чи програма там — частий спосіб закріпитися.", todo: "Якщо не знаєш, звідки файл, — перенеси його в карантин." },
      "forced-extension": { title: "Примусове розширення браузера", why: "Розширення встановлене політикою, тож його не можна вимкнути в браузері. Так роблять компанії на робочих комп'ютерах — і рекламне ПЗ.", todo: "Якщо комп'ютер не робочий — знайди розширення за ідентифікатором і видали політику." },
      "browser-proxy-policy": { title: "Проксі в політиці браузера", why: "Увесь трафік браузера примусово йде через вказаний сервер — він бачить, що ти відкриваєш.", todo: "Якщо комп'ютер не робочий — це ознака втручання." },
      hosts: { title: "Запис у файлі hosts", why: "Файл hosts переважає DNS: сайт відкривається за вказаною тут адресою або блокується.", todo: "Якщо ти сам не блокував рекламу — прибери запис із файлу hosts." },
      proxy: { title: "Проксі для інтернету", why: "Увесь веб-трафік іде через вказаний сервер.", todo: "Перевір у Параметри → Мережа → Проксі, чи ти це вмикав." },
      dns: { title: "DNS-сервер вручну", why: "DNS перетворює назви сайтів на адреси. Чужий DNS може тихо підсовувати фальшиві сайти.", todo: "Якщо не налаштовував сам — поверни автоматичне отримання DNS." },
      "defender-exclusion": { title: "Виключення антивіруса", why: "Захисник Windows не перевіряє цей шлях. Шкідливе ПЗ додає себе сюди, щоб його не знайшли.", todo: "Якщо не додавав сам — прибери виключення в Захиснику." },
      "root-cert": { title: "Доданий кореневий сертифікат", why: "Власник кореневого сертифіката може видавати себе за будь-який сайт і читати HTTPS-трафік. Їх додають антивіруси (для перевірки HTTPS), лаунчери ігор для локальної роботи — і шкідливе ПЗ.", todo: "Якщо не впізнаєш видавця — видали сертифікат (certmgr.msc)." },
      masquerade: { title: "Самозванець під системною назвою", why: "Програма носить назву системного процесу Windows, але це не він.", todo: "Перевір репутацію файлу, заверши процес і перенеси файл у карантин." },
      "double-extension": { title: "Подвійне розширення", why: "Файл вдає документ чи картинку (наприклад, «рахунок.pdf.exe»), а насправді це програма.", todo: "Майже завжди шкідливе — заверши процес і перенеси файл у карантин." },
      "odd-location": { title: "Програма з тимчасової папки", why: "Програма запущена з Temp, Завантажень чи спільної папки, а не встановлена. Так поводяться інсталятори — і шкідливе ПЗ.", todo: "Якщо це не інсталятор, який ти щойно запустив, — перевір репутацію." },
    },
