    actualClockHint: "The clock work is actually running at right now, turbo included, as Windows measures it: busy cores count more than idle ones. So it is higher than a plain average over all cores (like HWiNFO's “Average active”).",
    cpuTempShort: "Temperature",
    acpiHint: "The temperature of the thermal zone next to the CPU, as the BIOS reports it. Works without drivers; updates every few seconds.",
