  slowdown: {
    button: "Why is it slow?",
    title: "Why it is slow right now",
    watching: "Watching the computer for a few seconds…",
    hint: "Keep the heavy program open if it is the one that is slow: that way it shows up.",
    again: "Check again",
    cpu: "CPU",
    memory: "memory",
    disk: "disk",
    showProcess: "Show in Processes",
    toProcesses: "Open Processes",
    toMonitoring: "Open Monitoring",
    toCleanup: "Open Cleanup",
    toPower: "Power settings",
    cause: {
      "all-clear": { title: "Nothing is slowing it down right now", text: "The CPU is {{cpu}}% busy, memory {{memory}}%, the disk {{disk}}%. If one particular program is slow, the cause is most likely in that program — or the internet (check Network)." },
      thermal: { title: "The CPU is slowed by heat", text: "It is hot ({{temp}} °C) and lowers its own clock. Raise the back of the laptop, keep it off blankets; if it is always like this, it needs cleaning." },
      paging: { title: "Memory has run out", text: "Windows keeps reading memory back from disk ({{pages}} pages a second) — the most common cause of stutters. {{name}} uses the most. Close tabs and programs you do not need." },
      "memory-full": { title: "Memory is almost full", text: "{{memory}}% used. A little more and Windows starts moving data to disk, slowing everything. {{name}} uses the most." },
      "memory-tight": { title: "Memory is tight", text: "{{memory}}% used. It still works, but there is little headroom. {{name}} uses the most." },
      "cpu-busy": { title: "The CPU is {{cpu}}% busy", text: "{{name}} uses most of it ({{share}}% of the whole CPU). If you do not need that program right now, close it." },
      "busy-update": { title: "Windows is installing updates", text: "The CPU is {{cpu}}% busy with Windows Update. It is temporary: let it finish and do not switch off midway." },
      "busy-antivirus": { title: "The antivirus is scanning", text: "The CPU is {{cpu}}% busy with an antivirus scan. It usually takes a few minutes; full scans can be moved to the night in the antivirus settings." },
      "busy-indexer": { title: "Windows is indexing files for search", text: "After installing programs or copying many files this is normal and will finish soon." },
      "disk-busy": { title: "The disk is {{busy}}% busy", text: "Programs are waiting for the disk. {{name}} loads it the most." },
      "disk-update": { title: "The disk is busy with Windows Update", text: "The disk is {{busy}}% busy — Windows is downloading or installing updates. Temporary." },
      "disk-antivirus": { title: "The disk is busy with an antivirus scan", text: "The disk is {{busy}}% busy: the antivirus is scanning files. Temporary." },
      "disk-indexer": { title: "The disk is busy with search indexing", text: "The disk is {{busy}}% busy: Windows is indexing files for search. Temporary." },
      "power-saver": { title: "Power saving is on", text: "Windows deliberately limits the CPU to make the battery last. For speed, switch the power mode to Balanced or Best performance." },
      "on-battery": { title: "The laptop is on battery", text: "On battery the CPU and graphics run slower than on the charger. For heavy work, plug it in." },
      "drive-full": { title: "The system drive is nearly full", text: "Only {{free}}% is free. Windows lacks room for temporary files and updates — that slows everything." },
      "just-started": { title: "The computer has just started", text: "Only {{seconds}} s have passed. Startup programs are still loading — the first minutes being slow is normal. If it takes long every time, see Startup." },
      "long-uptime": { title: "No restart for {{days}} days", text: "Windows' Shut down does not fully reset the system (fast startup). Restarting every few days frees memory and finishes updates." },
    },
  },
