  whatsnew: {
    title: "What's new in DelphEye {{version}}",
    lead: "Click anything to try it right away.",
    ok: "Great",
    items: {
      phone: { title: "Your phone as a Wi-Fi sensor", text: "An Android app: a live compass to the router and your place on the home map, live." },
      shield: { title: "A 3D protection shield", text: "Seven sections: threats, browsers, backups, network, passwords — each explained." },
      overlay: { title: "An island over games", text: "FPS, temperatures and ping over any window. Ctrl+Shift+F12 shows it." },
      health: { title: "PC health history", text: "Temperatures, load and crashes by day — over a month, a quarter and a year." },
      wifi: { title: "Wi-Fi for guests", text: "A QR code so guests join without reading the password aloud." },
      look: { title: "Light theme and motion", text: "A new theme, a refreshed look and smooth transitions everywhere." },
      single: { title: "Just one window", text: "Starting DelphEye again no longer opens a second copy — it shows the open one." },
      phones: { title: "Headphones in one press", text: "Take Bluetooth headphones from the phone to the PC or let them go: in the island, with Ctrl+Shift+F10 or from the tray. Connecting takes up to 20 seconds." },
      vpnPing: { title: "Ping with a VPN", text: "The island and the connection check no longer say there is no network while a VPN is on." },
      layout: { title: "Tidier in any window", text: "The side menu scrolls in a low window, and pages line up on a wide screen." },
      cityPlan: { title: "The file city became a real city", text: "Roads run from the plaza straight to every district, and the districts are built up — a bigger folder has more buildings." },
      scale: { title: "Fits any window size", text: "Maximize the window and the whole interface grows in proportion and stays centred; in a narrow window nothing overlaps." },
      city: { title: "The file city", text: "The disk as a town: folder districts, buildings, branch roads from the centre, beacons on what is critical — and an explanation for every building." },
      disk3d: { title: "The disk in 3D", text: "While indexing, the drive is built live as a 3D model." },
      crashes: { title: "Why the PC shut down", text: "The stability section now names the exact cause of a crash, not just that it happened." },
      privacy: { title: "More on camera and mic", text: "A notice when an app turns on the camera or microphone, and quick access to block it." },
      watcher: { title: "A clearer Watcher", text: "Sections with explanations, and the sample alert shows in the island when it is on." },
      updates: { title: "Updates past \"app is open\"", text: "If a program cannot update because it is open, DelphEye offers to close it and retry." },
    },
  },
