      lsass: { what: "Checks passwords, PINs and fingerprints at sign-in and hands out access rights. Malware tries to steal from it, so it is specially protected." },
      svchost: { what: "A container for Windows services: one copy can run several services at once, which is why there are so many. Which services run in this one is listed below.", end: "The services inside stop. Windows restarts some of them, but others (network, sound, updates) stay gone until a restart. If a service slows the system, better turn it off in Startup → Services." },
      fontdrvhost: { what: "Processes fonts in an isolated environment so a malicious font cannot harm the system." },
